// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 warpTime, address payer) public {
        vm.assume(warpTime > 0 && warpTime < type(uint64).max);
        vm.assume(payer != address(0));

        uint256 before = c.pastBlockTime();

        vm.warp(warpTime);
        vm.assume(block.timestamp > before);

        vm.deal(payer, 10 ether);
        vm.prank(payer);
        (bool ok, ) = payable(address(c)).call{value: 10 ether}("");
        assertTrue(ok);

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
